static int test_atmosphere_params_default(void)
{
    printf("  TEST: Atmosphere params default initialization\n");

    alwan_atmosphere_params params;
    alwan_atmosphere_params_default(&params);

    /* Verify defaults match colour-science constants */
    TEST_ASSERT_NEAR(params.CO2_concentration, ALWAN_LITERAL(300.0), ALWAN_LITERAL(1e-10),
                     "Default CO2 should be 300 ppm");
    TEST_ASSERT_NEAR(params.temperature, ALWAN_LITERAL(288.15), ALWAN_LITERAL(1e-10),
                     "Default temperature should be 288.15 K");
    TEST_ASSERT_NEAR(params.pressure, ALWAN_LITERAL(101325.0), ALWAN_LITERAL(1e-10),
                     "Default pressure should be 101325 Pa");
    TEST_ASSERT_NEAR(params.latitude, ALWAN_LITERAL(0.0), ALWAN_LITERAL(1e-10),
                     "Default latitude should be 0 degrees");
    TEST_ASSERT_NEAR(params.altitude, ALWAN_LITERAL(0.0), ALWAN_LITERAL(1e-10),
                     "Default altitude should be 0 meters");

    return 0;
}

static int test_cross_section_default(void)
{
    printf("  TEST: Cross section with default parameters\n");

    for (size_t i = 0; i < NUM_WAVELENGTHS; i++) {
        alwan_scalar sigma = alwan_rayleigh_cross_section(wavelengths_nm[i], NULL);
        char msg[64];
        sprintf(msg, "Cross section at %.0f nm", wavelengths_nm[i]);
        TEST_ASSERT_REL(sigma, ref_cross_section_default[i], TEST_TOLERANCE, msg);
    }

    return 0;
}

static int test_cross_section_co2(void)
{
    printf("  TEST: Cross section at 555nm with different CO2 levels\n");

    alwan_atmosphere_params params;
    alwan_atmosphere_params_default(&params);

    for (size_t i = 0; i < NUM_CO2_LEVELS; i++) {
        params.CO2_concentration = co2_levels[i];
        alwan_scalar sigma = alwan_rayleigh_cross_section(555.0, &params);
        char msg[64];
        sprintf(msg, "Cross section at CO2 = %.0f ppm", co2_levels[i]);
        TEST_ASSERT_REL(sigma, ref_cross_section_co2_555nm[i], TEST_TOLERANCE, msg);
    }

    return 0;
}

