static int test_optical_depth_combined(void)
{
    printf("  TEST: Optical depth with combined location parameters\n");

    alwan_atmosphere_params params;
    alwan_atmosphere_params_default(&params);
    const char* locations[] = {"Paris", "Denver", "High altitude"};

    for (int i = 0; i < 3; i++) {
        params.latitude = combined_params[i * 2];
        params.altitude = combined_params[i * 2 + 1];
        alwan_scalar depth = alwan_rayleigh_optical_depth(555.0, &params);
        char msg[64];
        sprintf(msg, "Optical depth at %s", locations[i]);
        TEST_ASSERT_REL(depth, ref_optical_depth_combined[i], TEST_TOLERANCE, msg);
    }

    return 0;
}

static int test_spd(void)
{
    printf("  TEST: Spectral distribution generation\n");

    alwan_scalar out[100];
    int out_count;

    int status = alwan_rayleigh_spd(
        (alwan_scalar)spd_params[0],  /* start */
        (alwan_scalar)spd_params[1],  /* end */
        (alwan_scalar)spd_params[2],  /* step */
        NULL,
        out,
        &out_count
    );

    TEST_ASSERT(status == ALWAN_OK, "SPD generation failed");
    TEST_ASSERT(out_count == (int)NUM_SPD_VALUES, "SPD count mismatch");

    for (int i = 0; i < out_count; i++) {
        char msg[64];
        sprintf(msg, "SPD value at index %d", i);
        TEST_ASSERT_REL(out[i], ref_spd_default[i], TEST_TOLERANCE, msg);
    }

    return 0;
}

static int test_spd_error_handling(void)
{
    printf("  TEST: SPD error handling\n");

    alwan_scalar out[100];
    int out_count;
    int status;

    /* Test null output pointer */
    status = alwan_rayleigh_spd(360, 780, 10, NULL, NULL, &out_count);
    TEST_ASSERT(status == -1, "Should return error for null output");

    /* Test null count pointer */
    status = alwan_rayleigh_spd(360, 780, 10, NULL, out, NULL);
    TEST_ASSERT(status == -1, "Should return error for null count");

    /* Test invalid step */
    status = alwan_rayleigh_spd(360, 780, 0, NULL, out, &out_count);
    TEST_ASSERT(status == -1, "Should return error for zero step");

    /* Test invalid range */
    status = alwan_rayleigh_spd(780, 360, 10, NULL, out, &out_count);
    TEST_ASSERT(status == -1, "Should return error for invalid range");

    return 0;
}

/* ================================================================
 * Test Suite
 * ================================================================ */

typedef int (*test_func)(void);

typedef struct {
    const char *name;
    test_func func;
} test_case;

static test_case test_cases[] = {
    {"Atmosphere params default", test_atmosphere_params_default},
    {"Cross section default", test_cross_section_default},
    {"Cross section CO2 variation", test_cross_section_co2},
    {"Optical depth default", test_optical_depth_default},
    {"Optical depth pressure", test_optical_depth_pressure},
    {"Optical depth latitude", test_optical_depth_latitude},
    {"Optical depth altitude", test_optical_depth_altitude},
    {"Optical depth combined", test_optical_depth_combined},
    {"SPD generation", test_spd},
    {"SPD error handling", test_spd_error_handling},
};

#define NUM_TEST_CASES (sizeof(test_cases) / sizeof(test_cases[0]))

int test_49_rayleigh_scattering_main(void)
{
    int failed = 0;

    for (size_t i = 0; i < NUM_TEST_CASES; i++) {
        if (test_cases[i].func() != 0) {
            failed++;
        }
    }

    printf("Rayleigh Scattering: %d/%d tests passed\n",
           (int)NUM_TEST_CASES - failed, (int)NUM_TEST_CASES);

    return failed;
}
